{
  "headline": "FDA's records trace our supply to a plant classified OAI 257 days before the posting",
  "headline_cites": ["E10", "D1"],
  "sentences": [
    {
      "text": "The label for our succinylcholine chloride names Eugia Pharma Specialities Limited as the manufacturing plant.",
      "cites": ["E12"]
    },
    {
      "text": "FDA inspection 1301166 at that plant ended on 2026-02-06 and was classified OAI.",
      "cites": ["E10"]
    },
    {
      "text": "The OAI classification was known to FDA on 2026-09-21, which is 257 days before the shortage posting date of 2026-07-23.",
      "cites": ["E10", "E13", "D1"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2024-08-15 following an earlier OAI inspection.",
      "cites": ["E11", "E8"]
    },
    {
      "text": "Fresenius Kabi USA, LLC has discontinued manufacture of succinylcholine chloride, with an initial posting date of 2026-07-23.",
      "cites": ["E13"]
    },
    {
      "text": "Corvale East has 20 days on hand and Corvale General has 26 days on hand at current usage rates.",
      "cites": ["D1", "D2"]
    }
  ]
}
